insert into public.courses (name, location, architect, year_opened, description, website_url, source, source_ref, ratings_checked_at)
values ('Erin Hills', 'Erin, WI', null, 1995, 'Erin Hills is a golf course in the north central United States, located in Erin, Wisconsin, in Washington County, 35 miles (55 km) northwest of Milwaukee. The course officially opened in 2006. It hosted the 117th U.S. Open in 2017. The announcement was made in 2010. It was the first USGA regular men''s event ever awarded to a course owned by an individual. The 2011 U.S. Amateur, won by Kelly Kraft, was also held at Erin Hills.', 'https://www.erinhills.com/', 'opengolfapi', 'c11311e7-51b8-4495-adbc-355748feef56', now())
